    public function parse_market(array $market): array {
        //  {
        //    "symbol" => "BTC_USDT",
        //    "type" => "SPOT",
        //    "baseCurrency" => "BTC",
        //    "quoteCurrency" => "USDT",
        //    "basePrecision" => 6,
        //    "quotePrecision" => 2,
        //    "amountPrecision" => 8,
        //    "minAmount" => "10",
        //    "minTradeSize" => "0.000001",
        //    "maxTradeSize" => "1000",
        //    "minTradeDumping" => "0.000001",
        //    "maxTradeDumping" => "100",
        //    "enable" => true,
        //    "buyCeiling" => "1.1",
        //    "sellFloor" => "0.9"
        //  }
        $baseId = $this->safe_string($market, 'baseCurrency');
        $quoteId = $this->safe_string($market, 'quoteCurrency');
        $type = $this->safe_string_lower($market, 'type');
        $spot = $type === 'spot';
        $id = $baseId . '/' . $quoteId;
        return array(
            'symbol' => $id,
            'id' => $id,
            'spot' => $spot,
            'type' => $type,
            'base' => $baseId,
            'quote' => $quoteId,
            'baseId' => $baseId,
            'quoteId' => $quoteId,
            'active' => $this->safe_bool($market, 'enable'),
            'maker' => 0.0005,
            'taker' => 0.0005,
            'limits' => array(
                'amount' => array(
                    'min' => $this->safe_number($market, 'minTradeSize'),
                    'max' => $this->safe_number($market, 'maxTradeSize'),
                ),
            ),
            'precision' => array(
                'amount' => $this->safe_number($market, 'amountPrecision'),
                'price' => $this->safe_number($market, 'basePrecision'),
                // 'qoute' => $this->safe_number($market, 'quotePrecision'),
            ),
            'info' => $market,
            'contract' => false,
            'contractSize' => null,
            'created' => null,
            'expiry' => null,
            'expiryDatetime' => null,
            'future' => !$spot,
