    public function fetch_ohlcv(string $symbol, $timeframe = '1m', ?int $since = null, ?int $limit = null, $params = array ()): PromiseInterface {
        return Async\async(function () use ($symbol, $timeframe, $since, $limit, $params) {
            /**
             * fetches historical candlestick $data containing the open, high, low, and close price, and the volume of a $market
             * @see https://pionex-doc.gitbook.io/apidocs/restful/markets/get-$klines
             * @param {string} $symbol unified $symbol of the $market to fetch OHLCV $data for
             * @param {string} $timeframe the length of time each candle represents
             * @param {int} [$since] timestamp in ms of the earliest candle to fetch
             * @param {int} [$limit] the maximum amount of candles to fetch
             * @param {array} [$params] extra parameters specific to the exchange API endpoint
             * @return {int[][]} A list of candles ordered, open, high, low, close, volume
             */
            Async\await($this->load_markets());
            $market = $this->market($symbol);
            $request = array(
                'symbol' => $this->market_api_symbol($market['id']),
            );
            if ($timeframe !== null) {
                $request['interval'] = $this->timeframes[$timeframe];
            }
            if ($limit !== null) {
                $request['limit'] = min ($limit, 500); // default 100, max 500
            }
            if ($since !== null) {
                $duration = $this->parse_timeframe($timeframe);
                $request['endTime'] = min ($this->sum($since, $duration * $limit * 1000), $this->milliseconds());
            }
            $response = Async\await($this->publicGetMarketKlines ($this->extend($request, $params)));
            $data = $this->safe_dict($response, 'data', array());
            $klines = $this->safe_list($data, 'klines', array());
            // {
            // "result" => true,
            // "data" => {
            //     "klines" => array(
            //     array(
            //         "time" => 1691649240000,
            //         "open" => "1851.27",
            //         "close" => "1851.32",
            //         "high" => "1851.32",
            //         "low" => "1851.27",
            //         "volume" => "0.542"
            //     }
            //     )
            // ),
            // "timestamp" => 1691649271544
            // }
            return $this->parse_ohlcvs($klines, $market, $timeframe, $since, $limit);
        }) ();
    }

    public function parse_ohlcv($ohlcv, ?array $market = null): array {
        // {
        //     "time" => 1691649240000,
        //     "open" => "1851.27",
        //     "close" => "1851.32",
        //     "high" => "1851.32",
        //     "low" => "1851.27",
        //     "volume" => "0.542"
        // }
        return array(
            $this->safe_integer($ohlcv, 'time'),  // timestamp
            $this->safe_number($ohlcv, 'open'),  // open
            $this->safe_number($ohlcv, 'high'),  // high
            $this->safe_number($ohlcv, 'low'),  // low
            $this->safe_number($ohlcv, 'close'),  // close
            $this->safe_number($ohlcv, 'volume'),  // volume
        );
    }

    public function fetch_tickers(?array $symbols = null, $params = { }): PromiseInterface {
        return Async\async(function () use ($symbols, $params) {
            /**
             * fetches price $tickers for multiple markets, statistical information calculated over the past 24 hours for each market
             * @see https://pionex-doc.gitbook.io/apidocs/restful/markets/get-24hr-$ticker
             * @see https://pionex-doc.gitbook.io/apidocs/restful/markets/get-book-$ticker
             * @param {string[]|null} $symbols unified $symbols of the markets to fetch the $ticker for, all market $tickers are returned if not assigned
             * @param {array} [$params] extra parameters specific to the exchange API endpoint
             * @return {array} a dictionary of $ticker structures]
             */
            Async\await($this->load_markets());
            if ($params['type'] === null) {
                $params['type'] = 'SPOT';
            }
            $request = $params;
            $response = Async\await($this->publicGetMarketTickers ($request));
            // {
            // "data" => {
            //     "tickers" => array(
            //     array(
            //         "symbol" => "BTC_USDT",
            //         "time" => 1545291675000,
            //         "open" => "7962.62",
            //         "close" => "7952.32",
            //         "high" => "7971.61",
            //         "low" => "7950.29",
            //         "volume" => "1.537",
            //         "amount" => "12032.56",
            //         "count" => 271585
            //     ),
            //     array(
            //         "symbol" => "ETH_USDT",
            //         "time" => 1545291675000,
            //         "open" => "1963.62",
            //         "close" => "1852.22",
            //         "high" => "1971.11",
            //         "low" => "1850.23",
            //         "volume" => "100.532",
            //         "amount" => "112012.51",
            //         "count" => 432211
            //     }
            //     )
            // ),
            // "result" => true,
            // "timestamp" => 1566691672311
            // }
            $response2 = Async\await($this->publicGetMarketBookTickers ($request));
            // {
            // "data" => array(
            //     "tickers" => array(
            //     )
            // ),
            // "result" => true,
            // "timestamp" => 1566691672311
            // }
            $data = $this->safe_dict($response, 'data', array());
            $data2 = $this->safe_dict($response2, 'data', array());
            $tickers = $this->safe_list($data, 'tickers', array());
            $tickers2 = $this->safe_list($data2, 'tickers', array());
            $symbolsChanged = array();
            if ($symbols === null) {
                $symbols = array();
                for ($i = 0; $i < count($this->symbols); $i++) {
                    $symbol = $this->symbols[$i];
                    $symbols[$i] = str_replace('/', '_', $symbol);
                    $symbolsChanged[] = $this->market_api_symbol($symbols[$i]);
                }
            }
            $tickers = $this->filter_by_array($tickers, 'symbol', $symbolsChanged);
            $tickers2 = $this->filter_by_array($tickers2, 'symbol', $symbolsChanged);
            $tickersFinal = array();
            $unmatchedTickers = array();
            for ($i = 0; $i < count($tickers); $i++) {
                $ticker = $tickers[$i];
                $ticker['symbol'] = str_replace('_', '/', $ticker['symbol']);
                for ($j = 0; $j < count($tickers2); $j++) {
                    $ticker2 = $tickers2[$j];
                    $ticker2['symbol'] = str_replace('_', '/', $ticker2['symbol']);
                    if ($ticker2['symbol'] === $ticker['symbol']) {
                        $tickersFinal[] = $this->extend($ticker, $ticker2);
                    } else {
                        $unmatchedTickers[$i] = $ticker;
                        $tickersFinal[] = $ticker2;
                    }
                }
            }
            for ($i = 0; $i < count($unmatchedTickers); $i++) {
                $ticker = $unmatchedTickers[$i];
                $tickersFinal[] = $ticker;
            }
            $tickersFinal = $this->filter_by_array($tickersFinal, 'symbol', $this->symbols);
            return $this->parse_tickers($tickersFinal, $this->symbols);
        }) ();
    }

    public function fetch_ticker(string $symbol, $params = array ()): PromiseInterface {
        return Async\async(function () use ($symbol, $params) {
            /**
             * fetches a price ticker, a statistical calculation with the information calculated over the past 24 hours for a specific $market
             * @see https://pionex-doc.gitbook.io/apidocs/restful/markets/get-24hr-ticker
             * @see https://pionex-doc.gitbook.io/apidocs/restful/markets/get-book-ticker
             * @param {string} $symbol unified $symbol of the $market to fetch the ticker for
             * @param {array} [$params] extra parameters specific to the exchange API endpoint
             * @return {array} a ~@link https://docs.ccxt.com/#/?id=ticker-structure ticker structure~
             */
            Async\await($this->load_markets());
            $market = $this->market($symbol);
