    public function parse_balance($response): array {
        // {
        // "data" => {
        //     "balances" => array(
        //     array(
        //         "coin" => "BTC",
        //         "free" => "0.9000000",
        //         "frozen" => "0.00000000"
        //     ),
        //     array(
        //         "coin" => "USDT",
        //         "free" => "100.00000000",
        //         "frozen" => "900.00000000"
        //     }
        //     )
        // ),
        // "result" => true,
        // "timestamp" => 1566691672311
        // }
        $data = $this->safe_dict($response, 'data', array());
        $balances = $this->safe_list($data, 'balances', array());
        $timestamp = $this->safe_string($response, 'timestamp');
        $result = array(
            'info' => $balances,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
        );
        for ($i = 0; $i < count($response); $i++) {
            $balance = $balances[$i];
            $currencyId = $this->safe_string($balance, 'coin');
            $code = $this->safe_currency_code($currencyId);
            $account = $this->account();
            $account['free'] = $this->safe_string($balance, 'free');
            $frozen = $this->safe_number($balance, 'frozen');
            $account['total'] = (+$account['free'] . (string) $frozen);
            $result[$code] = $account;
        }
        return $this->safe_balance($result);
    }

