    public function parse_order(array $order, ?array $market = null): array {
        // {
        //     "orderId" => 1234567890,
        //     "symbol" => "BTC_USDT",
        //     "type" => "LIMIT",
        //     "side" => "SELL",
        //     "price" => "30000.00",
        //     "size" => "0.1000",
        //     "filledSize" => "0.0500",
        //     "filledAmount" => "1500.00",
        //     "fee" =>  "0.15",
        //     "feeCoin" =>  "USDT",
        //     "status" => "OPEN",
        //     "IOC" =>  false,
        //     "clientOrderId" =>  "9e3d93d6-e9a4-465a-a39c-2e48568fe194",
        //     "source" => "API",
        //     "createTime" => 1566676132311,
        //     "updateTime" => 1566676132311
        // }
        $timestamp = $this->safe_number($order, 'createTime');
        $size = $this->safe_number($order, 'size');
        $filledSize = $this->safe_number($order, 'filledSize');
        $side = $this->safe_string_lower($order, 'side');
        $remaining = $size - $filledSize;
        $average = 0;
        if ($filledSize) {
            $average = $this->safe_number($order, 'filledAmount') / $filledSize;
        }
        if ($side === 'buy') {
            $remaining = $filledSize - $size;
        }
        return $this->safe_order(array(
            'id' => $this->safe_string($order, 'orderId'),
            'clientOrderId' => $this->safe_string($order, 'clientOrderId'),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'lastTradeTimestamp' => $this->safe_number($order, 'updateTime'),
            'status' => $this->safe_string_lower($order, 'status'),
            'symbol' => str_replace('_', '/', $this->safe_string($order, 'symbol')),
            'type' => $this->safe_string_lower($order, 'type'),
            'timeInForce' => null,
            'postOnly' => $this->safe_bool($order, 'IOC'),
            'side' => $side,
            'price' => $this->safe_number($order, 'price'),
            'stopPrice' => null,
            'triggerPrice' => $this->safe_number($order, 'price'),
            'amount' => $size,
            'filled' => $filledSize,
            'remaining' => $remaining,
            'cost' => $this->safe_number($order, 'fee'),
            'trades' => null,
            'average' => $average,
            'fee' => array(
                'currency' => $this->safe_string($order, 'feeCoin'),
                'cost' => $this->safe_string($order, 'fee'),
            ),
            'info' => $order,
        ), $market);
    }

