    public function create_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array ()) {
        return Async\async(function () use ($symbol, $type, $side, $amount, $price, $params) {
            /**
             * create a trade order
             * @see https://pionex-doc.gitbook.io/apidocs/restful/orders/new-order
             * @param {string} $symbol unified $symbol of the $market to create an order in
             * @param {string} $type 'market' or 'limit'
             * @param {string} $side 'buy' or 'sell'
             * @param {float} $amount how much of currency you want to trade in units of base currency
             * @param {float} [$price] the $price at which the order is to be fulfilled, in units of the quote currency, ignored in $market orders
             * @param {array} [$params] extra parameters specific to the exchange API endpoint
             * @return {array} an ~@link https://docs.ccxt.com/#/?id=order-structure order structure~
             */
            Async\await($this->load_markets());
            $market = $this->market($symbol);
            $clientOrderId = $this->safe_string_2($params, 'client_order_id', 'clientOrderId', $this->uuid());
            $request = array(
                'symbol' => $this->market_api_symbol($market['id']),
                'side' => strtoupper($side),
                'type' => strtoupper($type),
                'amount' => $this->amount_to_precision($symbol, $amount),
                'size' => $this->amount_to_precision($symbol, $amount),
                'IOC' => $this->safe_bool($params, 'postOnly', false),
                'clientOrderId' => $clientOrderId,
            );
            if ($price) {
                $request['price'] = $price;
            }
            $response = $this->privatePostTradeOrder ($this->extend($request, $params));
            // {
            //     "data" => array(
            //         "orderId" => 1234567890,
            //         "clientOrderId" =>  "9e3d93d6-e9a4-465a-a39c-2e48568fe194"
            //     ),
            //     "result" => true,
            //     "timestamp" => 1566691672311
            // }
            $data = $this->safe_dict($response, 'data', array());
            $request['orderId'] = $data['orderId'];
            return $this->parse_order($request, $market);
        }) ();
    }

    public function create_orders(array $orders, $params = array ()) {
        return Async\async(function () use ($orders, $params) {
            /**
             * create a list of trade $orders
             * @see https://pionex-doc.gitbook.io/apidocs/restful/orders/new-multiple-order
             * @param {Array} $orders list of $orders to create, each object should contain the parameters required by createOrder, namely $symbol, $type, $side, $amount, $price and $params
             * @param {array} [$params]  extra parameters specific to the exchange API endpoint
             * @return {array} an ~@link https://docs.ccxt.com/#/?id=order-structure order structure~
             */
            Async\await($this->load_markets());
            $ordersRequests = array();
            for ($i = 0; $i < count($orders); $i++) {
                $rawOrder = $orders[$i];
                $symbol = $this->safe_string($rawOrder, 'symbol');
                $type = $this->safe_string($rawOrder, 'type');
                $side = $this->safe_string_upper($rawOrder, 'side');
                $amount = $this->safe_number($rawOrder, 'amount');
                $price = $this->safe_number($rawOrder, 'price');
                $orderParams = $this->safe_dict($rawOrder, 'params', array());
                $orderRequest = $this->create_order_request($symbol, $type, $side, $amount, $price, $orderParams);
                $ordersRequests[] = $orderRequest;
            }
            $firstOrder = $ordersRequests[0];
            $firstSymbol = $this->safe_string($firstOrder, 'symbol');
            $request = array(
                'symbol' => $firstSymbol,
                'orders' => $ordersRequests,
            );
            $response = $this->privatePostTradeMassOrder ($this->extend($request, $params));
            $data = $this->safe_dict($response, 'data', array());
            $orderIds = $this->safe_list($data, 'orderIds', array());
            $responseOrders = array();
            for ($i = 0; $i < count($orderIds); $i++) {
                $responseOrder = $this->safe_dict($orderIds, $i, array());
                $orderRequests = $this->safe_dict($ordersRequests, $i, array());
                $orderRequests['orderId'] = $responseOrder['orderId'];
                $responseOrders[] = $orderRequests;
            }
            return $this->parse_orders($responseOrders);
        }) ();
    }

    public function sign($path, $api = 'public', $method = 'GET', $params = array (), $headers = null, $body = null) {
        $endpointPath = '/api/v1/' . $this->implode_params($path, $params);
        $url = $this->urls['api'][$api] . $endpointPath;
        $params = $this->omit($params, $this->extract_params($path));
        if ($params && $method === 'GET' && $api !== 'private') {
            $url .= '?' . $this->urlencode($params);
        }
        if ($api === 'private') {
            if ($params && ($method === 'POST' || $method === 'DELETE')) {
                $body = $this->json($params);
            }
            $params['timestamp'] = $this->milliseconds();
            $url .= '?' . $this->urlencode($params);
            $sortedParams = $this->keysort($params);
            $structedPath = $method . $endpointPath . '?' . $this->urlencode($sortedParams);
            if ($body) {
                $structedPath = $structedPath . $body;
            }
            $signature = $this->hmac($this->encode($structedPath), $this->encode($this->secret), 'sha256');
            $headers = array(
                'Content-Type' => 'application/json',
                'PIONEX-KEY' => $this->apiKey,
                'PIONEX-SIGNATURE' => $signature,
            );
        }
        return array( 'url' => $url, 'method' => $method, 'body' => $body, 'headers' => $headers );
    }

    public function handle_errors(int $code, string $reason, string $url, string $method, array $headers, string $body, $response, $requestHeaders, $requestBody) {
        if ($response === null) {
            return null; // fallback to the default error handler
        }
        if (!$this->safe_bool($response, 'result', false)) {
            $feedback = $this->id . ' ' . $this->json($response);
            $this->throw_exactly_matched_exception($this->exceptions, $this->safe_string($response, 'code'), $feedback);
            throw new ExchangeError($feedback);
        }
        return null;
    }

    public function create_order_request(?string $symbol, string $type, string $side, ?float $amount, ?float $price = null, $params = array ()) {
        $market = $this->market($symbol);
        $clientOrderId = $this->safe_string_2($params, 'client_order_id', 'clientOrderId', $this->uuid());
        $params = $this->omit($params, array( 'client_order_id', 'clientOrderId' ));
        $request = array(
            'clientOrderId' => $clientOrderId,
            'side' => $side,
            'symbol' => $this->market_api_symbol($market['id']),
            'type' => 'LIMIT',  // Only support LIMIT.
            'size' => $this->amount_to_precision($symbol, $amount),
            'price' => $price,
        );
        return $this->extend($request, $params);
    }

    public function market_api_symbol(?string $symbol) {
        return str_replace('/', '_', $symbol);
    }
}
